# -*- coding: utf-8 -*-
# Сверка с ответами учебника Мерзляк 10, часть 4 (расхождения 150–187): пересчитано вручную + SymPy (check_mz4.py), условия сверены со сканом.
KB = "ключ неверен (сверка с ответом учебника Мерзляк 10 и пересчёт вручную): "
SRC = "сверка с ответами учебника Мерзляк 10 (углублённый) 25.09 + пересчёт вручную"
P = {}
def K(t, k, note, **kw):
    P[t] = {"k": k, "why": KB + note, "src": SRC}; P[t].update(kw)
OLD = lambda v, n: [(v, "прежний (неверный) ключ: " + n)]
K("G10_TB_§40_40_14", r"$8$ см и $2\sqrt{3}$ см", "высота к гипотенузе h = 4√3; S(y) = 16y(1 − y/h) максимальна при y = h/2 = 2√3, тогда вторая сторона 8 (было 4√3 и 4 — такой прямоугольник не вписывается)")
K("G10_TB_§39_39_18_2", r"возрастает на $(-\dfrac{\pi}{3} + \pi k; -\dfrac{\pi}{6} + \pi k)$, убывает на $(-\dfrac{\pi}{6} + \pi k; \dfrac{2\pi}{3} + \pi k)$, $x = -\dfrac{\pi}{6} + \pi k$ — точки максимума, $x = -\dfrac{\pi}{3} + \pi k$ — точки минимума, $k \in \mathbb{Z}$",
  "f′ = −2sin 2x − √3 > 0 ⇔ sin 2x < −√3/2 ⇔ x ∈ (−π/3 + πk; −π/6 + πk) (было (−7π/12; −π/12))")
K("G10_TB_§37_37_15", r"$y = -5$; $y = \dfrac{17}{3}$", "f′ = x² − 2x − 3 = 0 ⇒ x = 3, x = −1; f(3) = −5, f(−1) = 17/3 (было −5/3 и 13)")
K("G10_TB_§35_35_23_2", r"$-27$; $27$", "1/(3∛x²) = 1/27 ⇒ ∛x² = 9 ⇒ x = ±27 (был только корень 27)")
K("G10_TB_§42_42_40_2", r"Наибольшего и наименьшего значений не существует", "выражение определено при α ≠ πk/2 и равно 4cos²α − 1, где cos²α ∈ (0; 1): значения (−1; 3), границы не достигаются (было max 3, min −1)")
K("G10_TB_§26_26_11", r"$a = \dfrac{1}{2}$", "−4a² + 4a − 2 = −(2a − 1)² − 1 ≥ −1 только при a = 1/2; ключ был записан вырожденным отрезком [1/2; 1/2]")
K("G10_TB_§40_40_1_4", r"Наибольшее значение: $-4$, наименьшее значение: $-8$", "f′ = (x − 4)(x + 2)/(x − 1)²; f(−3) = −4,25, f(−2) = −4, f(0) = −8 (было наибольшее −2)",
  dadd=OLD(r"Наибольшее значение: $-2$, наименьшее значение: $-8$", "неверное наибольшее"))
K("G10_TB_§38_38_4_4", r"Возрастает на $(-\infty; -2]$ и $[10; +\infty)$, убывает на $[-2; 4)$ и $(4; 10]$", "f′ = (x² − 8x − 20)/(x − 4)² = (x − 10)(x + 2)/(x − 4)² (было −1 и 9)")
K("G10_TB_§39_39_15_5", r"возрастает на $[0; 4)$ и $(4; +\infty)$, убывает на $(-\infty; -4)$ и $(-4; 0]$, $x=0$ — точка минимума", "f′ = 2x/(16 − x²)²: убывает при x < 0, возрастает при x > 0, 0 — минимум (было наоборот, 0 — максимум)")
K("G10_TB_§39_39_22_4", r"возрастает на $(-\infty; 2{,}5]$, убывает на $[2{,}5; 3)$, $x = 2{,}5$ — точка максимума", "f′ = (5 − 2x)/(2(3 − x)^{3/2}), критическая точка 2,5 (было −1)")
K("G10_TB_§40_40_3_2", r"Наибольшее значение: $5$, наименьшее значение: $\sqrt{13}$", "подкоренное выражение возрастает на [2; 4]: f(2) = √13, f(4) = √25 = 5 (было √19)")
K("G10_TB_§10_10_7_3", r"$x \in (-\infty; -1) \cup (7; +\infty)$", "степень с нецелым показателем −1/9 определена только при положительном основании: x² − 6x − 7 > 0 (было и (−1; 7))",
  dadd=OLD(r"$x \in (-\infty; -1) \cup (-1; 7) \cup (7; +\infty)$", "допущено отрицательное основание степени с дробным показателем"))
K("G10_TB_§38_38_13_2", r"Убывает на $[-\dfrac{\pi}{4}+2\pi k; \dfrac{\pi}{4}+2\pi k]$, возрастает на $[\dfrac{\pi}{4}+2\pi k; \dfrac{7\pi}{4}+2\pi k]$, $k \in \mathbb{Z}$", "f′ = √2/2 − cos x ≥ 0 ⇔ cos x ≤ √2/2 (было: убывает на [−π/4; 7π/4])")
K("G10_TB_§31_31_7_4", r"$x = 2\pi k$; $x = \dfrac{\pi}{4} + \pi k$, $k \in \mathbb{Z}$", "(1 − cos x)(1 − tg x) = 0 ⇒ x = 2πk или x = π/4 + πk (ключ был списком десятичных приближений отдельных корней); вариант «2πk; π/4 + 2πk; 5π/4 + 2πk» равен ответу — закрыт", drop=[2])
P["G10_TB_§42_42_15_3"] = {"q": r"Решите неравенство: $\dfrac{(x+2)(x-5)}{(x-3)^{2}} \leq 0$", "src": SRC,
  "why": "в условии была искажена запись, ключ верен для восстановленного условия: номер пункта «3)» прилип как множитель, а дробь (x + 2)(x − 5)/(x − 3)² была переписана как (x + 2)((x − 5)/(x − 3))² (Мерзляк 10, № 42.15 (3))"}
